function balanceOfBatch(address[] memory accounts, uint256[] memory ids)
        public
        view
        virtual
        override
        returns (uint256[] memory)
    {
        // REQUIRE CHANGED: if (accounts.length == ids.length) -> allow ids.length >= accounts.length by using accounts.length
        // (original required exact match; mutant truncates ids when longer)
        // require(accounts.length == ids.length, "ERC1155: accounts and ids length mismatch");

        uint256 len = accounts.length;
        // if ids is shorter than accounts, still revert as before
        require(ids.length >= len, "ERC1155: accounts and ids length mismatch");

        uint256[] memory batchBalances = new uint256[](len);

        for (uint256 i = 0; i < len; ++i) {
            batchBalances[i] = balanceOf(accounts[i], ids[i]);
        }

        return batchBalances;
    }

